fixtures = []
for node_id, spec in specs.items():
    positive = positive_content(node_id)
    fixtures.append(fixture(node_id, 'positive', 'positive', positive))
    wrong_source = json.loads(json.dumps(positive))
    for evidence in wrong_source['evidence']:
        evidence['source_role'] = 'company_style_only'
    fixtures.append(fixture(node_id, 'wrong-source', 'wrong_source', wrong_source))
    skeleton = {'facts': [], 'claims': [], 'evidence': [], 'objects': [{'object_kind': 'table', 'occurrences': 1, 'text': None, 'cells': []}]}
    fixtures.append(fixture(node_id, 'skeleton', 'skeleton', skeleton))
    missing = json.loads(json.dumps(positive))
    if spec['negative_kind'] == 'missing_claim':
        missing['claims'] = missing['claims'][1:]
        fixtures.append(fixture(node_id, 'missing-claim', 'missing_claim', missing))
    else:
        missing['facts'] = missing['facts'][1:]
        fixtures.append(fixture(node_id, 'missing-control', 'missing_control', missing))
    suffix, expected_code = spec['negative']
    if suffix not in {'missing-control', 'missing-claim'}:
        specific = json.loads(json.dumps(positive))
        if suffix == 'copied-company-name':
            specific['facts'].append({'fact_path': 'data_management.template_company_name', 'value': '合成复制公司名称'})
        elif suffix == 'study-data-conflated-with-future-use':
            specific['claims'] = [claim for claim in specific['claims'] if claim['claim_type'] != 'future_use.separation']
        elif suffix == 'blank-custody-period':
            specific['facts'] = [fact for fact in specific['facts'] if fact['fact_path'] != 'retention.custody']
        elif suffix == 'nonexistent-repository':
